/**
 * components/ui/alert-dialog.tsx
 *
 * Confirmation dialog — focus-trapped, scroll-lock safe.
 */
import * as React from 'react'

import { Portal } from '~/components/primitives/portal'
import { useLatest } from '~/hooks/use-latest'
import { cx } from '~/lib/cx'
import { lockBodyScroll, trapFocus } from '~/lib/overlay'
import { Button } from './button'
import styles from './alert-dialog.module.scss'

export interface AlertDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  title?: string
  description?: string
  cancelText?: string
  actionText?: string
  onAction?: () => void
  onCancel?: () => void
  destructive?: boolean
  className?: string
  children?: React.ReactNode
}

export function AlertDialog({
  open,
  onOpenChange,
  title,
  description,
  cancelText = 'Cancel',
  actionText = 'Continue',
  onAction,
  onCancel,
  destructive = false,
  className,
  children,
}: AlertDialogProps) {
  const titleId = React.useId()
  const descId = React.useId()
  const [panel, setPanel] = React.useState<HTMLDivElement | null>(null)
  const onOpenChangeRef = useLatest(onOpenChange)

  React.useEffect(() => {
    if (!open || !panel) return
    const unlock = lockBodyScroll()
    const releaseTrap = trapFocus(panel, () =>
      onOpenChangeRef.current(false),
    )
    return () => {
      releaseTrap()
      unlock()
    }
  }, [open, panel, onOpenChangeRef])

  if (!open) return null

  const handleCancel = () => {
    onCancel?.()
    onOpenChange(false)
  }

  const handleAction = () => {
    onAction?.()
  }

  return (
    <Portal>
      <div className={styles.root}>
        <div
          className={styles.overlay}
          aria-hidden="true"
          onClick={handleCancel}
        />

        <div
          ref={setPanel}
          role="alertdialog"
          aria-modal="true"
          aria-labelledby={title ? titleId : undefined}
          aria-describedby={description ? descId : undefined}
          tabIndex={-1}
          className={cx(styles.panel, className)}
          onClick={(event) => event.stopPropagation()}
        >
          <div className={styles.content}>
            {title ? (
              <h2 id={titleId} className={styles.title}>
                {title}
              </h2>
            ) : null}

            {description ? (
              <p id={descId} className={styles.description}>
                {description}
              </p>
            ) : null}

            {children}
          </div>

          <div className={styles.actions}>
            <Button variant="outline" onClick={handleCancel}>
              {cancelText}
            </Button>
            <Button
              variant={destructive ? 'destructive' : 'primary'}
              onClick={handleAction}
            >
              {actionText}
            </Button>
          </div>
        </div>
      </div>
    </Portal>
  )
}

export { AlertDialog as ConfirmationDialog }

@use 'styles' as vz;

.root {
  position: fixed;
  inset: 0;
  z-index: vz.z('modal');
  display: flex;
  align-items: center;
  justify-content: center;
  padding: vz.space(4);
}

.overlay {
  position: absolute;
  inset: 0;
  background: vz.color('foreground', 0.45);
  backdrop-filter: blur(6px);
  animation: vz-alert-dialog-overlay-in vz.duration('base') vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.panel {
  position: relative;
  width: 100%;
  max-width: 28rem;
  border: 1px solid vz.color('border', 0.8);
  border-radius: vz.radius('2xl');
  background: vz.color('card');
  color: vz.color('card-foreground');
  box-shadow: vz.elevation(3);
  outline: none;
  animation: vz-alert-dialog-in vz.duration('slow') vz.ease('out') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

.content {
  display: flex;
  flex-direction: column;
  gap: vz.space(2);
  padding: vz.space(6) vz.space(6) 0;
}

.title {
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('lg');
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

.description {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  line-height: 1.5;
}

.actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: vz.space(2);
  padding: vz.space(4) vz.space(6);
}

@keyframes vz-alert-dialog-overlay-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes vz-alert-dialog-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: none;
  }
}
